using CapitalPos.Application.Seguridad; using CapitalPos.Domain;
namespace CapitalPos.Application.Inventario;
public sealed class ListarKardexUseCase(IMovimientoInventarioRepository repository, IEmpresaActivaContext empresa) { public async Task<IReadOnlyCollection<MovimientoInventario>> EjecutarAsync(Guid? productoId,Guid? productoVarianteId,Guid? sedeId,DateOnly desde,DateOnly hasta,CancellationToken c=default) { if(!empresa.TieneEmpresaActiva) throw new InvalidOperationException("La empresa activa es obligatoria."); if(desde>hasta) throw new ArgumentException("El rango de fechas no es valido."); return (await repository.ListarPorEmpresaAsync(empresa.EmpresaId,c)).Where(x=>(!productoId.HasValue||x.ProductoId==productoId)&&(!productoVarianteId.HasValue||x.ProductoVarianteId==productoVarianteId)&&(!sedeId.HasValue||x.SedeId==sedeId)&&DateOnly.FromDateTime(x.FechaCreacion.ToOffset(TimeSpan.FromHours(-5)).Date)>=desde&&DateOnly.FromDateTime(x.FechaCreacion.ToOffset(TimeSpan.FromHours(-5)).Date)<=hasta).ToArray(); } }
